91	  /**
92	   * Wraps a command in a subshell `()` to capture background process IDs (PIDs) using pgrep.
93	   * Uses newlines to prevent breaking heredocs or trailing comments.
94	   *
95	   * @param command The raw command string to execute.
96	   * @param tempFilePath Path to the temporary file where PIDs will be written.
97	   * @param isWindows Whether the current platform is Windows (if true, the command is returned as-is).
98	   * @returns The wrapped command string.
99	   */
100	  private wrapCommandForPgrep(
101	    command: string,
102	    tempFilePath: string,
103	    isWindows: boolean,
104	  ): string {
105	    if (isWindows) {
106	      return command;
107	    }
108	    let trimmed = command.trim();
109	    if (!trimmed) {
110	      return '';
111	    }
112	    if (trimmed.endsWith('\\')) {
113	      trimmed += ' ';
114	    }
115	    const escapedTempFilePath = escapeShellArg(tempFilePath, 'bash');
116	    return `(\n${trimmed}\n)\n__code=$?; pgrep -g 0 >${escapedTempFilePath} 2>&1; exit $__code;`;
117	  }
